"""Generate additive catalog SQL from reviewed fictional operational data."""
from pathlib import Path
import json
root=Path(__file__).resolve().parents[1]
d=json.loads((root/'database/catalog.json').read_text(encoding='utf8'))
def q(v):return "'"+str(v).replace("'","''")+"'"
sql=['-- Generated by tools/build-catalog.py. Fictional operational sample data.',
     '-- Reapplying never resets availability, passwords, assignments or custom records.',
     "ALTER TABLE locations ADD COLUMN IF NOT EXISTS area VARCHAR(100) NOT NULL DEFAULT 'Bengaluru';",
     'ALTER TABLE locations ADD COLUMN IF NOT EXISTS street TEXT;',
     'ALTER TABLE locations ADD COLUMN IF NOT EXISTS campus TEXT;',
     'ALTER TABLE locations ADD COLUMN IF NOT EXISTS building TEXT;',
     'ALTER TABLE locations ADD COLUMN IF NOT EXISTS aliases TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[];']
for table,key,rows,cols in [('emergency_types','type_id',d['incidentTypes'],'type_id,type_name,description'),('capabilities','capability_id',d['capabilities'],'capability_id,capability_name,description'),('resource_types','type_id',d['resourceTypes'],'type_id,type_name,description')]:
 for r in rows:sql.append(f"INSERT INTO {table}({cols}) VALUES({r['id']},{q(r['name'])},{q(r['description'])}) ON CONFLICT({key}) DO NOTHING;")
for r in d['locations']:
 aliases='ARRAY['+','.join(q(a) for a in r['aliases'])+']::TEXT[]'
 if r['id']>3:
  sql.append(f"INSERT INTO locations(location_id,location_name,address,risk_level,area,street,aliases) VALUES({r['id']},{q(r['name'])},{q(r['street']+', '+r['area'])},'medium',{q(r['area'])},{q(r['street'])},{aliases}) ON CONFLICT(location_id) DO NOTHING;")
 else:
  sql.append(f"UPDATE locations SET location_name={q(r['name'])},address={q(r['street']+', '+r['area'])},area={q(r['area'])},street={q(r['street'])},aliases={aliases} WHERE location_id={r['id']} AND (area='Bengaluru' OR location_name LIKE 'Demo %');")
for r in d['locations']:
 if r.get('campus'):
  sql.append(f"UPDATE locations SET campus={q(r['campus'])},building={q(r.get('building',''))} WHERE location_id={r['id']} AND location_name={q(r['name'])};")
for old,new in [('Demo Coordinator','Operations Coordinator'),('Demo Firefighter','Fire Response Lead'),('Demo Medic','Medical Response Lead'),('Demo Rescue Worker','Water Rescue Lead'),('Demo Technician','Maintenance Officer')]:
 sql.append(f'UPDATE users SET full_name={q(new)} WHERE full_name={q(old)};')
for old,new in [('Demo Fire Engine','Central Fire Engine'),('Demo Ambulance','Campus Ambulance'),('Demo Rescue Boat','Riverside Rescue Boat')]:
 sql.append(f'UPDATE resources SET resource_name={q(new)} WHERE resource_name={q(old)};')
sql.extend(["UPDATE emergencies SET description=regexp_replace(description,'^Training ','') WHERE description LIKE 'Training %';",
 "UPDATE emergency_required_capabilities c SET location_name=l.location_name,address=l.address FROM locations l WHERE c.location_id=l.location_id AND (c.location_name LIKE 'Demo %' OR c.address LIKE 'Training %');"])
for r in d['resources']:
 sql.append(f"INSERT INTO resources(resource_id,type_id,resource_name,call_sign,status,current_location_id,capacity) VALUES({r['id']},{r['type']},{q(r['name'])},{q(r['callSign'])},'available',{r['location']},{r['capacity']}) ON CONFLICT(resource_id) DO NOTHING;")
 for cap in r['capabilities']:sql.append(f"INSERT INTO resource_capabilities(resource_id,capability_id,proficiency_level) VALUES({r['id']},{cap},'qualified') ON CONFLICT DO NOTHING;")
 for tag in ['operational',r['callSign'].split('-')[0].lower()]:sql.append(f"INSERT INTO resource_tags(resource_id,tag) VALUES({r['id']},{q(tag)}) ON CONFLICT DO NOTHING;")
for resource,cap in [(202,12),(203,16)]:sql.append(f"INSERT INTO resource_capabilities(resource_id,capability_id,proficiency_level) VALUES({resource},{cap},'qualified') ON CONFLICT DO NOTHING;")
for r in d['responders']:
 sql.append(f"INSERT INTO responders(responder_id,user_id,employee_id,team,status) VALUES({r['id']},NULL,{q(r['employee'])},{q(r['team'])},'available') ON CONFLICT(responder_id) DO NOTHING;")
 for skill in r['skills']:sql.append(f"INSERT INTO responder_skills(responder_id,skill) VALUES({r['id']},{q(skill)}) ON CONFLICT DO NOTHING;")
for table,key in [('emergency_types','type_id'),('capabilities','capability_id'),('resource_types','type_id'),('locations','location_id'),('resources','resource_id'),('responders','responder_id')]:
 sql.append(f"SELECT setval(pg_get_serial_sequence('{table}','{key}'),GREATEST((SELECT MAX({key}) FROM {table}),(SELECT last_value FROM {table}_{key}_seq)),true);")
(root/'database/09_operational_catalog.sql').write_text('\n'.join(sql)+'\n',encoding='utf8')
counts={'roles':3,'users':5,'emergency_types':12,'locations':len(d['locations'])+len(json.loads((root/'database/area-landmarks.json').read_text(encoding='utf8'))),'emergencies':3,'emergency_status_history':6,'capabilities':16,'emergency_required_capabilities':3,'responders':15,'resource_types':14,'resources':20,'resource_capabilities':6+sum(len(r['capabilities']) for r in d['resources']),'assignments':3,'maintenance_records':3,'responder_reports':3,'responder_skills':6+sum(len(r['skills']) for r in d['responders']),'resource_tags':6+2*len(d['resources'])}
(root/'database/catalog-summary.json').write_text(json.dumps({'freshTableCounts':counts,'freshDomainRows':sum(counts.values()),'areas':len(d['areas'])},indent=2)+'\n')
print(json.dumps({'domainRows':sum(counts.values()),'resources':counts['resources'],'locations':counts['locations']}))
